// C++98 legacy approach
class LegacyWidget {
private:
  void processPointer(void* ptr); // Declared but not defined
};

// C++11 modern approach
class ModernWidget {
public:
  // Any attempt to call this will result in a compile-time error
  void processPointer(void* ptr) = delete;
};

// Template specialization example
class Processor {
public:
  template<typename T>
  void process(T* ptr) { /* generic implementation */ }
};

// Delete the void* specialization at namespace scope
template<>
void Processor::process<void>(void* ptr) = delete;
